-- PERIKSA abt-alasan-belum-dipilih-30okt (BACA SAJA). Baris terakhir harus "SEMUA COCOK".
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (4020,8530,8531,8532,8511,8512,8521,8522,8528,8529) AND MD5(REPLACE(sql_query, CONCAT(DATABASE(), '.'), 'aps_badilag.')) IN ('1b2b8bf22a3225e0bf7da0c7059de2e7','46c7070cbe12ac8881f9df253c091351','4ce9df877cf443006e5a7f06796850b7','5051ea609b678fadd08aea321fecf12a','6ec6591cb10f9927afbdca0562b95b53','701a846f237898ea9bf709622066efa0','7d03edaa4ddf9c305703328b8e04135b','97aed24a20a6a2948808b755e5d38756','9b0753819ac8d44460915ef0d59a903e','f6a1c35d4c429736e71537cab96cb913')) = 10
  AND (SELECT COUNT(*) FROM abt_variabel WHERE no_var IN (4020,8530,8531,8532,8511,8512,8521,8522,8528,8529) AND (LOCATE('<mark>TIDAK BENAR QUERY NYA / BELUM ISI ALASAN DI KOLOM ABT</mark>', sql_query) > 0 OR LOCATE('<mark>TIDAK BENAR QUERY NYA</mark>', sql_query) > 0)) = 0,
  'SEMUA COCOK', 'TIDAK COCOK') AS periksa;
